$ip='172.26.169.198'; $cred=New-Object System.Management.Automation.PSCredential('FakeWheel',(ConvertTo-SecureString 'FakeWheel!2026' -AsPlainText -Force)); $s=New-PSSession -ComputerName $ip -Credential $cred -ErrorAction Stop; Invoke-Command -Session $s -ScriptBlock { pnputil /add-driver C:\FakeWheel\fake_rs50hidkm.inf /install 2>&1; & C:\FakeWheel\devcon.exe install C:\FakeWheel\fake_rs50hidkm.inf 'root\FakeRs50HidKm' 2>&1 }; Start-Sleep 10; Invoke-Command -Session $s -ScriptBlock { Get-PnpDevice -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -match 'ROOT\SAMPLE|VHF|HID_DEVICE_SYSTEM_VHF' } | Select-Object Status,Class,FriendlyName,InstanceId,Problem | Format-Table -AutoSize | Out-String }; Remove-PSSession $s